command_executions.command:
/usr/bin/bash -lc 'for f in evidence/native_run/observations/step_*.json; do jq -r --arg f "$f" '"'
  def sw(list): [list[]? | select(.resource_name==\"android:id/switch_widget\") | .is_checked] | if length==0 then \"none\" else join(\",\") end;
  def title(list): [list[]? | select(.resource_name==\"com.android.settings:id/collapsing_toolbar\" or .resource_name==\"android:id/title\" or .resource_name==\"com.android.settings:id/switch_text\") | (.content_description // .text // empty)] | unique | join(\" | \");
  ["'$f, (title(.before_element_list)), (sw(.before_element_list)), (title(.after_element_list)), (sw(.after_element_list))] | @tsv'"' \""'$f"; done | sed '"'s#evidence/native_run/observations/##'"

